base = 0x16d;
while (base < 0x17c) {
    action = 0;
    mapped = base;
    int mapped_end = base + 5;
    do {
        if (key == mapped) {
            return provider->is_active(player, action);
        }
        ++action;
        ++mapped;
    } while (mapped < mapped_end);
    base = mapped;
    ++player;
}
